<template><view class="page"><view class="order-header"><view class="section-kicker">YOUR LITTLE HAPPINESS</view><view class="title">每一餐，都值得期待</view><view class="subtitle">你的校园美味记录</view><view class="chips types"><view :class="['chip',{selected:type==='DELIVERY'}]" @click="type='DELIVERY'">外卖配送</view><view :class="['chip',{selected:type==='PICKUP'}]" @click="type='PICKUP'">到店自取</view></view></view><scroll-view scroll-x class="status-scroll"><view class="chips"><view v-for="s in filters" :key="s.value" :class="['status-tab',{selected:status===s.value}]" @click="status=s.value">{{s.label}}</view></view></scroll-view><view class="content"><view v-if="pending" class="card link" @click="go('checkout/index')">上次下单结果待确认，点击恢复 →</view><view v-if="!state.token" class="empty"><view class="empty-symbol">▤</view><view>登录后，查看你的美味订单</view><button class="btn" @click="signIn">登录查看</button></view><template v-else><view v-if="error" class="error" @click="load">{{error}} · 重试</view><view v-for="o in filtered" :key="o.id" class="card" @click="go('order/index?id='+o.id)"><view class="between"><text class="bold">{{o.store_name}} ›</text><text class="order-status">{{o.refund_status==='REQUESTED'?'退款审核中':statuses[o.status]}}</text></view><view v-if="o.scheduled_at" class="subtitle">预约 {{String(o.scheduled_at).replace('T',' ')}}</view><view class="divider"/><view class="order-body"><image :src="o.items?.[0]?.image||o.store_image" mode="aspectFill"/><view><view>{{o.items?.[0]?.name}}</view><view class="subtitle small">共 {{o.items?.reduce((s,p)=>s+p.quantity,0)}} 件商品</view></view><text class="bold order-total">¥{{money(o.total)}}</text></view><view class="between footer"><text class="tiny muted">{{String(o.created_at).replace('T',' ').slice(0,16)}}</text><text class="pill">{{o.status==='UNPAID'?'去支付':'查看详情'}}</text></view></view><view v-if="loading&&!filtered.length" class="empty">正在加载订单…</view><view v-if="!loading&&!filtered.length&&!error" class="empty"><view class="empty-symbol">♧</view><view>这里还没有订单</view><view class="subtitle">去发现一份今天的小满足吧</view><button class="btn light" @click="home">去逛逛</button></view><button v-if="hasMore" class="btn light" :disabled="loading" :loading="loading" @click="more">加载更多订单</button></template></view><BottomNav active="orders"/></view></template>
<script setup>
import {ref,reactive,toRefs,computed,watch} from 'vue';import {onShow,onHide,onUnload} from '@dcloudio/uni-app';import BottomNav from '../../components/BottomNav.vue';import {state,request,login,go,money,statuses} from '../../lib/api';import {intents} from '../../lib/recovery';const pending=ref(false);import {createOrderFeed} from '../../lib/order-feed.mjs';
const type=ref('DELIVERY'),status=ref('');const feedState=reactive({rows:[],page:1,hasMore:false,loading:false,error:''});const {error,hasMore,loading}=toRefs(feedState);const filtered=computed(()=>feedState.rows);let timer,visible=false;
const feed=createOrderFeed(feedState,params=>request('/orders?page='+params.page+'&type='+encodeURIComponent(params.type)+'&status='+encodeURIComponent(params.status),'GET',null,true));const filters=[{label:'全部',value:''},...Object.entries(statuses).map(([value,label])=>({value,label}))];
function home(){uni.reLaunch({url:'/pages/home/index'})}async function signIn(){try{await login();await load()}catch(e){error.value=e.message}}function load(background=false){if(!state.token)return;return feed.reset({type:type.value,status:status.value},background)}function more(){return feed.more()}
watch([type,status],()=>{if(visible)load()});watch(()=>state.token,()=>{feed.cancel();feedState.rows=[];feedState.hasMore=false;if(visible&&state.token)load()});
onShow(()=>{pending.value=!!intents.read();visible=true;clearInterval(timer);load();timer=setInterval(()=>{if(feedState.page===1)load(true)},15000)});function stop(){visible=false;clearInterval(timer);feed.cancel()}onHide(stop);onUnload(stop);
</script>
<style scoped>.order-header{padding:55rpx 32rpx 30rpx;background:linear-gradient(135deg,#eaf0e2,#f7f8ee);padding-top:calc(55rpx + env(safe-area-inset-top))}.order-header .title{margin-top:14rpx}.types{margin-top:33rpx}.status-scroll{padding:24rpx 32rpx;background:#fff}.status-tab{color:#97a18e;font-size:25rpx;padding:8rpx 12rpx}.status-tab.selected{color:#3f7050;border-bottom:5rpx solid #769774;font-weight:700}.order-body{display:flex;align-items:center;gap:20rpx;font-size:26rpx}.order-body image{width:110rpx;height:110rpx;border-radius:16rpx}.order-total{margin-left:auto}.footer{margin-top:26rpx}</style>
